import pdfrw

# Read the PDF
pdf = pdfrw.PdfReader('/root/sc100-blank.pdf')

# List all form fields
print("Form Fields:")
print("=" * 80)

if pdf.Root.AcroForm is not None:
    for page_num, page in enumerate(pdf.pages):
        if page.Annots:
            for annotation in page.Annots:
                if annotation['/Subtype'] == '/Widget':
                    field_name = annotation.T
                    field_type = annotation.FT
                    if field_name:
                        print(f"Page {page_num}: {field_name} ({field_type})")
else:
    print("No form fields found in traditional AcroForm")

# Try to examine the structure
print("\n\nForm structure details:")
print(pdf.Root.AcroForm)

EOF
